const fs=require('fs'),path=require('path'),crypto=require('crypto'),assert=require('assert/strict');
const postcss=require(process.env.INK_POSTCSS_MODULE||'postcss');
const repo=process.env.INK_REPO_ROOT||process.cwd(),base=process.env.INK_QA_BASELINE;
assert(base,'Set INK_QA_BASELINE to the exact f7e387c product snapshot');
const dir=path.join(repo,'working/evidence/ink-ui-normalization-completion-20261002');
const hash=b=>crypto.createHash('sha256').update(b).digest('hex');
const contexts=r=>{let x=[];for(let p=r.parent;p&&p.type!=='root';p=p.parent)x.unshift(p.name+':'+p.params.replace(/\s/g,''));return x.join('/')};
const touched=new Set(['.layer-bottom-toolbar','.layers-panel .layer-opacity-card','.layer-thumb','.ui-b-layer-lock','.ui-b-layer-appearance','.layers-list','.panel-stack-tabs','.panel-stack-splitter','.panel-stack-splitter::after','.window-visual-controls svg']);
function metrics(file){const bytes=fs.readFileSync(file),root=postcss.parse(bytes.toString());let important=0,decls=0,groups=new Map(),fonts=[];const media=[];root.walkAtRules('media',r=>media.push(r.params.replace(/\s/g,'')));root.walkDecls(d=>{decls++;important+=!!d.important;if(d.prop==='font-size')fonts.push(contexts(d.parent)+'|'+d.parent.selector+'|'+d.value)});root.walkRules(r=>{if(touched.has(r.selector)){let k=contexts(r)+'|'+r.selector;groups.set(k,(groups.get(k)||0)+1)}});return{bytes:bytes.length,sha256:hash(bytes),declarations:decls,important,media:[...new Set(media)].sort(),fontDeclarations:fonts.sort(),coveredExactDuplicates:[...groups].filter(([k,n])=>n>1)}}
const before=metrics(path.join(base,'product/source/styles.css')),after=metrics(path.join(repo,'product/source/styles.css'));assert(after.important<=before.important);assert.deepEqual(after.media,before.media);assert.deepEqual(after.fontDeclarations,before.fontDeclarations);assert.equal(after.coveredExactDuplicates.length,0);
const allowed=new Set(['styles.css','index.html','index-standalone.html','shell.template.html','generate-shell.mjs','web-shell.js','ui/full-capability-controls.js','src/editor/creative-workspace.js','src/config.js','service-worker.js']);let files=[];
