const report={baseline:'f7e387c2977b3c69c160356bd368b4f387c602c2',before,after,productFiles:files.length,changed:files.filter(x=>x.changed),unchanged:files.filter(x=>!x.changed).length,files,scope:'UI presentation and existing panel state routing only; Core/history/format/renderer unchanged; config and service-worker BUILD_ID metadata only'};fs.mkdirSync(dir,{recursive:true});fs.writeFileSync(path.join(dir,'source-health.json'),JSON.stringify(report,null,2));console.log(JSON.stringify({before:{bytes:before.bytes,important:before.important},after:{bytes:after.bytes,important:after.important},changed:report.changed.map(x=>x.path),media:after.media,coveredExactDuplicates:after.coveredExactDuplicates}));
